const string p = "Transfer.";
if (ReadBool(p + "RefillRequested"))
{
    Write(p + "PumpOn", false);
    Write(p + "SourceLevel", 100.0);
    Write(p + "DestinationLevel", 0.0);
    Write(p + "RunRequested", true);
    Write(p + "RefillRequested", false);
    Write(p + "Status", "Refilled - restarting transfer");
}
else
{
    var source = ReadDouble(p + "SourceLevel");
    var destination = ReadDouble(p + "DestinationLevel");
    var requested = ReadBool(p + "RunRequested");
    if (!double.IsFinite(source) || !double.IsFinite(destination) || source < 0 || source > 100 || destination < 0 || destination > 100 || Math.Abs(source + destination - 100) > 0.0001)
    {
        Write(p + "PumpOn", false);
        Write(p + "RunRequested", false);
        Write(p + "Status", "Invalid levels - press Refill & Restart");
    }
    else if (source <= 0 || destination >= 100)
    {
        Write(p + "PumpOn", false);
        Write(p + "RunRequested", false);
        Write(p + "Status", "Transfer complete - press Refill & Restart");
    }
    else if (!requested)
    {
        Write(p + "PumpOn", false);
        Write(p + "Status", source >= 100 ? "Ready - press Start / Stop" : "Paused - press Start / Stop to resume");
    }
    else
    {
        var amount = Math.Min(1.0, Math.Min(source, 100.0 - destination));
        source -= amount;
        destination += amount;
        Write(p + "SourceLevel", source);
        Write(p + "DestinationLevel", destination);
        var active = source > 0 && destination < 100;
        Write(p + "PumpOn", active);
        if (!active) Write(p + "RunRequested", false);
        Write(p + "Status", active ? "Transferring - 4% per second" : "Transfer complete - press Refill & Restart");
    }
}

